assert!(matches!(inverse.as_slice(), [PdfVtMutation::RestoreDpartGraph(_)]));
let PdfVtMutation::RestoreDpartGraph(restore) = &inverse[0] else { unreachable!() };
let undo = <super::super::RestoreDpartGraph as MutationKind<PdfSnapshot, PdfVtMutation>>::diff(restore, &next);
let restored = undo.diff().apply(&next).unwrap();
assert_eq!(restored, base);

